#[test]
fn unsupported_capability_receipt_is_durable_and_consumes_the_sequence() {
    let path = database_path("capability-refusal");
    remove_database(&path);
    let inbox = SupervisorInbox::open(
        &path,
        registration(vec![SupervisorDirectiveCapability::Notify]),
        session(),
    )
    .expect("open inbox");
    let directive = directive(1, now() + Duration::minutes(10));

    let receipt = inbox.receive(&directive, now()).expect("record refusal");

    assert_eq!(receipt.status, v1::DirectiveReceiptStatus::Refused as i32);
    assert_eq!(
        receipt.reason,
        v1::DirectiveReceiptReason::CapabilityMissing as i32
    );
    assert_eq!(
        inbox.receive(&directive, now()).expect("replay refusal"),
        receipt
    );
    drop(inbox);
    remove_database(&path);
}

#[test]
fn expired_directive_receipt_is_durable() {
    let path = database_path("expired");
    remove_database(&path);
    let inbox = SupervisorInbox::open(
        &path,
        registration(vec![SupervisorDirectiveCapability::Prompt]),
        session(),
    )
    .expect("open inbox");
    let directive = directive(1, now() - Duration::seconds(1));

    let receipt = inbox.receive(&directive, now()).expect("record expiry");

    assert_eq!(receipt.status, v1::DirectiveReceiptStatus::Expired as i32);
    assert_eq!(receipt.reason, v1::DirectiveReceiptReason::Expired as i32);
    assert_eq!(
        inbox.receive(&directive, now()).expect("replay expiry"),
        receipt
    );
    drop(inbox);
    remove_database(&path);
}

